  1	/**
  2	 * Executor adapter factory.
  3	 *
  4	 * Two orthogonal env vars control executor selection:
  5	 *   EXECUTOR_PROFILE — infrastructure topology (how the executor is spawned)
  6	 *     "local-subprocess" (default) — fork a child process
  7	 *   EXECUTOR_TYPE — which agent binary runs
  8	 *     "claude" (default) — Claude executor
  9	 *     "hermes"           — Hermes executor
 10	 *
 11	 * Per-task routing (execution.runtime on task YAMLs) is deferred to
 12	 * agent-runtime-selector. Selection here is static at startup.
 13	 */
 14	
 15	import * as path from "node:path";
 16	import type { ExecutorPort, CompletionBrokerPort } from "@workflow/runtime-abi";
 17	import { SubProcessAdapter } from "./subprocess.js";
 18	
 19	function getBinPrefix(): string {
 20	  return process.env.EXECUTOR_BIN_PREFIX ?? "/workflow";
 21	}
 22	
 23	// ── Config ─────────────────────────────────────────────────────────────────────
 24	
 25	export interface ExecutorFactoryConfig {
 26	  /** Path to the compiled Claude executor dist directory (containing index.js). */
 27	  claudeExecutorDist?: string;
 28	  /** Path to the compiled Hermes executor dist directory (containing index.js). */
 29	  hermesExecutorDist?: string;
 30	
 31	  /** Hermes inference model ID (e.g. "deepseek-v4-flash"). */
 32	  hermesModel?: string;
 33	  /** Hermes inference provider (e.g. "deepseek"). */
 34	  hermesProvider?: string;
 35	  /** DeepSeek API credential — injected into Hermes executor env. */
 36	  deepseekApiKey?: string;
 37	  /** Optional RAG MCP server URL (written to HERMES_HOME/config.yaml by the executor). */
 38	  ragMcpUrl?: string;
 39	  /** Optional RAG MCP auth token. */
 40	  ragMcpToken?: string;
 41	  /** Optional max tool iterations for Hermes. Defaults to 150 inside the executor. */
 42	  hermesMaxTurns?: number;
 43	
 44	  /**
 45	   * Extra environment variables merged into the child env after executor-type
 46	   * env vars. Callers use this for per-task vars (TASK_BRANCH, MAX_TURNS, etc.).
 47	   * Executor-type vars resolved by resolveExecutorEnv take lower precedence — they
 48	   * are applied first; extraEnv can override them.
 49	   */
 50	  extraEnv?: Record<string, string>;
 51	
 52	  /** CompletionBrokerPort wired into the adapter for handle registration. */
 53	  broker?: CompletionBrokerPort;
 54	
 55	  /** Host directory under which per-handle exec dirs live. */
 56	  workspacesDir?: string;
 57	}
 58	
 59	// ── Helpers ────────────────────────────────────────────────────────────────────
 60	
 61	/**
 62	 * Resolve the executor binary path for the given executor type.
 63	 *
 64	 * Falls back to the default location under EXECUTOR_BIN_PREFIX when
 65	 * the config does not supply an explicit dist directory.
 66	 */
 67	export function resolveExecutorBin(
 68	  type: string,
 69	  config: ExecutorFactoryConfig,
 70	): string {
 71	  switch (type) {
 72	    case "hermes":
 73	      return path.join(
 74	        config.hermesExecutorDist ??
 75	          path.join(getBinPrefix(), "runtime", "executors", "hermes", "dist"),
 76	        "index.js",
 77	      );
 78	    case "claude":
 79	    default:
 80	      return path.join(
 81	        config.claudeExecutorDist ??
 82	          path.join(getBinPrefix(), "runtime", "executors", "claude", "dist"),
 83	        "index.js",
 84	      );
 85	  }
 86	}
 87	
 88	/**
 89	 * Resolve executor-type-specific environment variables.
 90	 *
 91	 * Hermes requires model/provider credentials injected via env because:
 92	 *   - The orchestrator must stay blind to executor internals.
 93	 *   - Env vars are the version-stable boundary between the two codebases.
 94	 *   - The same interface works for subprocess and future container topologies.
 95	 *
 96	 * Claude currently requires no extra env beyond what the ABI already provides.
 97	 */
 98	export function resolveExecutorEnv(
 99	  type: string,
100	  config: ExecutorFactoryConfig,
101	): Record<string, string> {
102	  switch (type) {
103	    case "hermes": {
104	      const env: Record<string, string> = {
105	        HERMES_INFERENCE_MODEL: config.hermesModel ?? "",
106	        HERMES_INFERENCE_PROVIDER: config.hermesProvider ?? "",
107	        DEEPSEEK_API_KEY: config.deepseekApiKey ?? "",
108	      };
109	      if (config.ragMcpUrl) env.RAG_MCP_URL = config.ragMcpUrl;
110	      if (config.ragMcpToken) env.RAG_MCP_TOKEN = config.ragMcpToken;
111	      if (config.hermesMaxTurns !== undefined) {
112	        env.HERMES_MAX_TURNS = String(config.hermesMaxTurns);
113	      }
114	      return env;
115	    }
116	    case "claude":
117	    default:
118	      return {};
119	  }
120	}
121	
122	// ── Factory ───────────────────────────────────────────────────────────────────
123	
124	/**
125	 * Create an ExecutorPort wired for the active EXECUTOR_PROFILE and EXECUTOR_TYPE.
126	 *
127	 * EXECUTOR_PROFILE selects the adapter class (infrastructure topology).
128	 * EXECUTOR_TYPE    selects the binary path and executor-specific env vars.
129	 *
130	 * Adding a new executor type: add a case to resolveExecutorBin / resolveExecutorEnv.
131	 * Adding a new topology:      add a case to the profile switch below.
132	 * The two axes never mix.
133	 */
134	export function createExecutorAdapter(config: ExecutorFactoryConfig): ExecutorPort {
135	  const profile = process.env.EXECUTOR_PROFILE ?? "local-subprocess";
136	  const executorType = process.env.EXECUTOR_TYPE ?? "claude";
137	
138	  switch (profile) {
139	    case "local-subprocess":
140	      return new SubProcessAdapter({
141	        executorBinPath: resolveExecutorBin(executorType, config),
142	        extraEnv: {
143	          ...resolveExecutorEnv(executorType, config),
144	          ...(config.extraEnv ?? {}),
145	        },
146	        broker: config.broker,
147	      });
148	
149	    default:
150	      throw new Error(`Unknown EXECUTOR_PROFILE: ${profile}`);
151	  }
152	}

