  1	/**
  2	 * DockerRunAdapter — ExecutorPort adapter for the local-docker profile (T8).
  3	 *
  4	 * submit() registers the handle with the broker, then runs:
  5	 *   docker run -d \
  6	 *     --name exec-<handle> \
  7	 *     --network agents-net \
  8	 *     --entrypoint /platform/runner.js \
  9	 *     --restart=no \
 10	 *     -v /platform-bin:/platform:ro \
 11	 *     -v /workspaces/<task>:/workspace:rw \
 12	 *     -e RESULT_PATH ... -e CALLBACK_URL ... \
 13	 *     --label platform.handle=<handle> \
 14	 *     executor:current
 15	 *
 16	 * The container runs the runner wrapper as PID 1. When the wrapper exits
 17	 * (after POSTing result to broker), the container exits naturally.
 18	 * `--rm` is NOT used so docker logs / inspect remain available until ack().
 19	 *
 20	 * Wrapper-crash safety net:
 21	 *   `docker wait <container_id>` is run in background. If the container
 22	 *   exits without a corresponding broker callback arriving within crashGraceMs,
 23	 *   the adapter synthesises a "failed" completion via the broker's callback URL.
 24	 *
 25	 * ack():
 26	 *   Runs `docker rm <container_id>` to clean up the exited container, and
 27	 *   unlinks the result file. Delegates to broker.ack() to commit consumption.
 28	 *
 29	 * Orphan sweep:
 30	 *   A periodic sweep scans `docker ps -a -f label=platform.handle=<handle>`
 31	 *   for exited containers whose handles are no longer in the supervision map
 32	 *   (i.e. have already been acked or are unknown) and removes them.
 33	 */
 34	
 35	import { unlinkSync } from "node:fs";
 36	import { join } from "node:path";
 37	import { execFile } from "node:child_process";
 38	import { promisify } from "node:util";
 39	import * as http from "node:http";
 40	import * as https from "node:https";
 41	import type {
 42	  ExecutorPort,
 43	  ExecutorPortInput,
 44	  ExecutorHandle,
 45	  ExecutorResult,
 46	  CompletionBrokerPort,
 47	} from "@workflow/runtime-abi";
 48	
 49	const execFileAsync = promisify(execFile);
 50	
 51	// ── Types ─────────────────────────────────────────────────────────────────────
 52	
 53	export interface DockerRunAdapterOpts {
 54	  /**
 55	   * Docker image to run as the executor.
 56	   * Defaults to the standard executor image tag.
 57	   */
 58	  executorImage?: string;
 59	
 60	  /**
 61	   * Path to the runner.js wrapper inside the container.
 62	   * Defaults to /platform/runner.js (mounted via platformBinDir).
 63	   */
 64	  runnerEntrypoint?: string;
 65	
 66	  /**
 67	   * Host path to the directory containing runner.js.
 68	   * Mounted read-only into the container at /platform.
 69	   * Defaults to /workflow/runtime/runner-wrapper (standard container path).
 70	   */
 71	  platformBinDir?: string;
 72	
 73	  /**
 74	   * Host directory under which per-handle workspace dirs live.
 75	   * Each executor gets an isolated subdirectory at `<workspacesDir>/exec-<handle>`.
 76	   * Mounted read-write into the container at /workspace.
 77	   * If not set, workspace mounting is skipped (tests may skip this).
 78	   */
 79	  workspacesDir?: string;
 80	
 81	  /**
 82	   * Docker bridge network the containers join so they can reach the broker
 83	   * by service-name DNS (e.g. `broker:7000`).
 84	   * Defaults to `agents-net`.
 85	   */
 86	  dockerNetwork?: string;
 87	
 88	  /**
 89	   * Maximum wall-clock milliseconds before the watchdog kills the container.
 90	   * Defaults to 2 hours.
 91	   */
 92	  timeoutMs?: number;
 93	
 94	  /**
 95	   * Grace window (ms) after container exit before the safety-net synthetic
 96	   * failure is posted to the broker. Allows a callback that was in-flight at
 97	   * crash time to arrive before we synthesize a failure.
 98	   * Default: 5 000 ms.
 99	   */
100	  crashGraceMs?: number;
101	
102	  /**
103	   * How often the orphan sweep runs (ms). Pass 0 to disable.
104	   * Default: 60 000 ms.
105	   */
106	  orphanSweepIntervalMs?: number;
107	
108	  /**
109	   * CompletionBrokerPort instance. Required for the async callback flow.
110	   * If absent, broker.register is skipped (useful in isolated unit tests).
111	   */
112	  broker?: CompletionBrokerPort;
113	
114	  /**
115	   * Extra environment variables passed to the container.
116	   */
117	  extraEnv?: Record<string, string>;
118	
119	  /**
120	   * Override the docker binary path (useful in tests).
121	   * Default: "docker".
122	   */
123	  dockerBin?: string;
124	}
125	
126	interface SupervisionEntry {
127	  containerId: string;
128	  containerName: string;
129	  startedAt: string; // ISO 8601
130	  nonce: string;
131	  callbackUrl: string;
132	  resultPath: string;
133	  taskId: string;
134	  featureId: string;
135	}
136	
137	// ── Defaults ──────────────────────────────────────────────────────────────────
138	
139	const DEFAULT_EXECUTOR_IMAGE = "executor:current";
140	const DEFAULT_RUNNER_ENTRYPOINT = "/platform/runner.js";
141	const DEFAULT_PLATFORM_BIN_DIR = "/workflow/runtime/runner-wrapper";
142	const DEFAULT_DOCKER_NETWORK = "agents-net";
143	const DEFAULT_TIMEOUT_MS = 7_200_000;
144	const DEFAULT_CRASH_GRACE_MS = 5_000;
145	const DEFAULT_ORPHAN_SWEEP_MS = 60_000;
146	
147	// ── Helpers ───────────────────────────────────────────────────────────────────
148	
149	function emit(event: Record<string, unknown>): void {
150	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
151	}
152	
153	/** HTTP POST — resolves regardless of response status. Rejects on transport error. */
154	function _httpPost(url: string, body: string): Promise<void> {
155	  return new Promise((resolve, reject) => {
156	    let u: URL;
157	    try {
158	      u = new URL(url);
159	    } catch {
160	      reject(new Error(`_httpPost: invalid URL: ${url}`));
161	      return;
162	    }
163	    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
164	    const req = lib.request(
165	      {
166	        hostname: u.hostname,
167	        port: u.port || (u.protocol === "https:" ? 443 : 80),
168	        path: u.pathname + u.search,
169	        method: "POST",
170	        headers: {
171	          "Content-Type": "application/json",
172	          "Content-Length": Buffer.byteLength(body),
173	        },
174	      },
175	      (res) => {
176	        res.resume();
177	        resolve();
178	      },
179	    );
180	    req.on("error", reject);
181	    req.write(body);
182	    req.end();
183	  });
184	}
185	
186	// ── DockerRunAdapter ──────────────────────────────────────────────────────────
187	
188	export class DockerRunAdapter implements ExecutorPort {
189	  private readonly executorImage: string;
190	  private readonly runnerEntrypoint: string;
191	  private readonly platformBinDir: string;
192	  private readonly workspacesDir: string | undefined;
193	  private readonly dockerNetwork: string;
194	  private readonly timeoutMs: number;
195	  private readonly crashGraceMs: number;
196	  private readonly orphanSweepIntervalMs: number;
197	  private readonly broker: CompletionBrokerPort | null;
198	  private readonly extraEnv: Record<string, string>;
199	  private readonly dockerBin: string;
200	
201	  /** Keyed by handle; tracks in-flight containers for the safety-net sweep. */
202	  private readonly supervision = new Map<ExecutorHandle, SupervisionEntry>();
203	
204	  private orphanSweepTimer: ReturnType<typeof setInterval> | null = null;
205	
206	  constructor(opts: DockerRunAdapterOpts = {}) {
207	    this.executorImage = opts.executorImage ?? DEFAULT_EXECUTOR_IMAGE;
208	    this.runnerEntrypoint = opts.runnerEntrypoint ?? DEFAULT_RUNNER_ENTRYPOINT;
209	    this.platformBinDir = opts.platformBinDir ?? DEFAULT_PLATFORM_BIN_DIR;
210	    this.workspacesDir = opts.workspacesDir;
211	    this.dockerNetwork = opts.dockerNetwork ?? DEFAULT_DOCKER_NETWORK;
212	    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
213	    this.crashGraceMs = opts.crashGraceMs ?? DEFAULT_CRASH_GRACE_MS;
214	    this.orphanSweepIntervalMs = opts.orphanSweepIntervalMs ?? DEFAULT_ORPHAN_SWEEP_MS;
215	    this.broker = opts.broker ?? null;
216	    this.extraEnv = opts.extraEnv ?? {};
217	    this.dockerBin = opts.dockerBin ?? "docker";
218	
219	    if (this.orphanSweepIntervalMs > 0) {
220	      this.orphanSweepTimer = setInterval(() => {
221	        this._orphanSweep().catch((err) => {
222	          emit({ type: "orphan_sweep_error", error: String(err) });
223	        });
224	      }, this.orphanSweepIntervalMs);
225	      if (this.orphanSweepTimer.unref) this.orphanSweepTimer.unref();
226	    }
227	  }
228	
229	  // ── ExecutorPort ──────────────────────────────────────────────────────────
230	
231	  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
232	    const {
233	      taskId,
234	      featureId,
235	      workspaceId,
236	      handle,
237	      taskRepoUrl,
238	      taskRepoBranch,
239	      taskBaseBranch,
240	      taskRepoBaseBranch,
241	      executorWorkdir,
242	      mgmtRepoUrl,
243	      resultPath,
244	      budgetTokens,
245	      implementationModel,
246	      sshPrivateKey,
247	      githubToken,
248	      callbackUrl,
249	      nonce,
250	    } = input;
251	    const startedAt = new Date().toISOString();
252	    const containerName = `exec-${handle}`;
253	
254	    // 1. Register handle with broker before spawning so callback arriving
255	    //    before submit returns is still accepted.
256	    if (this.broker) {
257	      await this.broker.register(handle, nonce, {
258	        kind: input.kind ?? "impl",
259	        task_id: taskId,
260	        feature_id: featureId,
261	        started_at: startedAt,
262	      });
263	    }
264	
265	    // 2. Build docker run arguments.
266	    const envArgs: string[] = [
267	      "-e", `TASK_ID=${taskId}`,
268	      "-e", `FEATURE_ID=${featureId}`,
269	      "-e", `WORKSPACE_ID=${workspaceId}`,
270	      "-e", `TASK_REPO_URL=${taskRepoUrl}`,
271	      "-e", `TASK_REPO_BRANCH=${taskRepoBranch}`,
272	      "-e", `TASK_BASE_BRANCH=${taskBaseBranch}`,
273	      ...(taskRepoBaseBranch !== undefined ? ["-e", `TASK_REPO_BASE_BRANCH=${taskRepoBaseBranch}`] : []),
274	      "-e", `EXECUTOR_WORKDIR=${executorWorkdir}`,
275	      "-e", `MGMT_REPO_URL=${mgmtRepoUrl}`,
276	      "-e", `RESULT_PATH=${resultPath}`,
277	      "-e", `GITHUB_TOKEN=${githubToken}`,
278	      "-e", `CALLBACK_URL=${callbackUrl}`,
279	      "-e", `HANDLE=${handle}`,
280	      "-e", `NONCE=${nonce}`,
281	    ];
282	
283	    if (sshPrivateKey) {
284	      envArgs.push("-e", `SSH_PRIVATE_KEY=${sshPrivateKey}`);
285	    }
286	    if (budgetTokens !== undefined) {
287	      envArgs.push("-e", `BUDGET_TOKENS=${budgetTokens}`);
288	    }
289	    if (implementationModel) {
290	      envArgs.push("-e", `IMPLEMENTATION_MODEL=${implementationModel}`);
291	    }
292	
293	    for (const [k, v] of Object.entries(this.extraEnv)) {
294	      envArgs.push("-e", `${k}=${v}`);
295	    }
296	
297	    const volumeArgs: string[] = [
298	      "-v", `${this.platformBinDir}:/platform:ro`,
299	    ];
300	    if (this.workspacesDir) {
301	      volumeArgs.push("-v", `${this.workspacesDir}/exec-${handle}:/workspace:rw`);
302	    }
303	
304	    const dockerArgs = [
305	      "run", "-d",
306	      "--name", containerName,
307	      "--network", this.dockerNetwork,
308	      "--entrypoint", this.runnerEntrypoint,
309	      "--restart=no",
310	      "--label", `platform.handle=${handle}`,
311	      ...envArgs,
312	      ...volumeArgs,
313	      this.executorImage,
314	    ];
315	
316	    emit({
317	      type: "executor_spawn",
318	      task_id: taskId,
319	      feature_id: featureId,
320	      handle,
321	      container_name: containerName,
322	      image: this.executorImage,
323	    });
324	
325	    // 3. docker run -d — returns container ID immediately.
326	    let containerId: string;
327	    try {
328	      const { stdout } = await execFileAsync(this.dockerBin, dockerArgs);
329	      containerId = stdout.trim();
330	    } catch (err) {
331	      // If docker run fails, unregister the handle and rethrow.
332	      if (this.broker) {
333	        await this.broker.ack(handle).catch(() => {/* best-effort */});
334	      }
335	      throw err;
336	    }
337	
338	    // 4. Track in supervision map.
339	    this.supervision.set(handle, {
340	      containerId,
341	      containerName,
342	      startedAt,
343	      nonce,
344	      callbackUrl,
345	      resultPath,
346	      taskId,
347	      featureId,
348	    });
349	
350	    // 5. docker wait as the wrapper-crash safety net (runs async).
351	    this._watchContainer(handle, containerId, containerName, callbackUrl, nonce, taskId, featureId);
352	
353	    return handle;
354	  }
355	
356	  /**
357	   * readResult is a no-op for local-docker — result rides in the callback.
358	   * Returns a tombstone so callers that mistakenly call readResult get a
359	   * predictable signal.
360	   */
361	  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
362	    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
363	  }
364	
365	  // ── ack ───────────────────────────────────────────────────────────────────
366	
367	  /**
368	   * Acknowledge a completed handle:
369	   *  - Removes the entry from the supervision map (disarms the safety net).
370	   *  - Runs `docker rm <container_id>` to clean up the exited container.
371	   *  - Unlinks the result file.
372	   *  - Delegates to broker.ack.
373	   */
374	  async ack(handle: ExecutorHandle): Promise<void> {
375	    const entry = this.supervision.get(handle);
376	    if (entry) {
377	      this.supervision.delete(handle);
378	
379	      // docker rm — best-effort; container may already be removed.
380	      try {
381	        await execFileAsync(this.dockerBin, ["rm", entry.containerId]);
382	      } catch {
383	        // Container may already be gone (manual cleanup, restart, etc.).
384	      }
385	
386	      // Unlink result file — best-effort.
387	      try {
388	        unlinkSync(entry.resultPath);
389	      } catch {
390	        // File may already be gone.
391	      }
392	
393	    }
394	
395	    if (this.broker) {
396	      await this.broker.ack(handle);
397	    }
398	  }
399	
400	  // ── Supervision helpers ───────────────────────────────────────────────────
401	
402	  /** Number of handles currently tracked in the supervision map. */
403	  supervisionSize(): number {
404	    return this.supervision.size;
405	  }
406	
407	  /** Stop the orphan sweep timer. Call during graceful shutdown. */
408	  stopOrphanSweep(): void {
409	    if (this.orphanSweepTimer) {
410	      clearInterval(this.orphanSweepTimer);
411	      this.orphanSweepTimer = null;
412	    }
413	  }
414	
415	  // ── Internal ─────────────────────────────────────────────────────────────
416	
417	  /**
418	   * Run `docker wait <containerId>` in the background. When the container
419	   * exits, if the handle is still in the supervision map (no callback arrived
420	   * yet), fire a synthetic "failed" completion to the broker after crashGraceMs.
421	   */
422	  private _watchContainer(
423	    handle: ExecutorHandle,
424	    containerId: string,
425	    containerName: string,
426	    callbackUrl: string,
427	    nonce: string,
428	    taskId: string,
429	    featureId: string,
430	  ): void {
431	    // Watchdog: kill the container if it exceeds the wall-clock timeout.
432	    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
433	      watchdog = null;
434	      emit({
435	        type: "executor_timeout",
436	        task_id: taskId,
437	        feature_id: featureId,
438	        handle,
439	        container_id: containerId,
440	        timeout_ms: this.timeoutMs,
441	      });
442	      execFileAsync(this.dockerBin, ["stop", containerName]).catch(() => {/* best-effort */});
443	    }, this.timeoutMs);
444	    if (watchdog.unref) watchdog.unref();
445	
446	    // docker wait — blocks until container exits; run async.
447	    execFileAsync(this.dockerBin, ["wait", containerId])
448	      .then(({ stdout }) => {
449	        const exitCode = parseInt(stdout.trim(), 10);
450	
451	        if (watchdog !== null) {
452	          clearTimeout(watchdog);
453	          watchdog = null;
454	        }
455	
456	        emit({
457	          type: "executor_exit",
458	          task_id: taskId,
459	          feature_id: featureId,
460	          handle,
461	          container_id: containerId,
462	          exit_code: exitCode,
463	        });
464	
465	        // Grace timer before firing safety net.
466	        const graceTimer = setTimeout(() => {
467	          if (!this.supervision.has(handle)) return; // already acked
468	          const entry = this.supervision.get(handle)!;
469	          this.supervision.delete(handle);
470	
471	          const reason =
472	            exitCode !== 0
473	              ? `runner_crashed (exit ${exitCode})`
474	              : "runner_no_callback";
475	
476	          emit({
477	            type: "executor_safety_net",
478	            task_id: entry.taskId,
479	            feature_id: entry.featureId,
480	            handle,
481	            container_id: containerId,
482	            reason,
483	          });
484	
485	          const body = JSON.stringify({
486	            handle,
487	            nonce: entry.nonce,
488	            result: { terminal_status: "failed", blocked_reason: reason },
489	          });
490	
491	          _httpPost(entry.callbackUrl, body).catch(() => {
492	            // Best-effort — ignore POST failures in the safety net.
493	          });
494	        }, this.crashGraceMs);
495	
496	        if (graceTimer.unref) graceTimer.unref();
497	      })
498	      .catch(() => {
499	        // docker wait failed (container removed before we could wait, etc.).
500	        // The safety net won't fire, but the broker's visibility timeout will
501	        // reclaim the completion eventually.
502	        if (watchdog !== null) {
503	          clearTimeout(watchdog);
504	          watchdog = null;
505	        }
506	      });
507	  }
508	
509	  /**
510	   * Periodic orphan sweep.
511	   *
512	   * Lists all containers with a `platform.handle` label, checks which ones
513	   * are exited and whose handles are NOT in the in-flight supervision map
514	   * (i.e. already acked or never registered), and removes them.
515	   */
516	  private async _orphanSweep(): Promise<void> {
517	    let stdout: string;
518	    try {
519	      const result = await execFileAsync(this.dockerBin, [
520	        "ps", "-a",
521	        "--filter", "label=platform.handle",
522	        "--format", "{{.ID}}\t{{.Label \"platform.handle\"}}\t{{.Status}}",
523	      ]);
524	      stdout = result.stdout;
525	    } catch {
526	      return; // docker unavailable; skip sweep
527	    }
528	
529	    const lines = stdout.trim().split("\n").filter(Boolean);
530	    for (const line of lines) {
531	      const [containerId, handle, status] = line.split("\t");
532	      if (!containerId || !handle || !status) continue;
533	
534	      // Only remove exited containers whose handles are not in supervision.
535	      if (status.toLowerCase().startsWith("exited") && !this.supervision.has(handle)) {
536	        emit({
537	          type: "orphan_container_removed",
538	          container_id: containerId,
539	          handle,
540	        });
541	        execFileAsync(this.dockerBin, ["rm", containerId]).catch(() => {/* best-effort */});
542	      }
543	    }
544	  }
545	}

