 1	/**
 2	 * local-docker profile factory.
 3	 *
 4	 * Bundles the Wave-4 adapter set into a RuntimePorts instance for the
 5	 * M:N multi-container topology: each orchestrator spawns per-task executor
 6	 * containers via `docker run -d`; all completions route through a shared
 7	 * Redis-backed broker service.
 8	 *
 9	 * Adapter set:
10	 *   ExecutorPort         → DockerRunAdapter     (docker run -d, --network agents-net)
11	 *   CompletionBrokerPort → HttpBrokerAdapter    (calls Go broker service at BROKER_URL)
12	 *   WorkflowState        → GitWorkflowStateAdapter
13	 *   Credential           → EnvCredentialAdapter
14	 *   WorkspacePull        → GitClonePullAdapter
15	 *   EventEmitter         → StdoutJsonEmitter
16	 *   Scheduler            → SimpleSleepScheduler
17	 *   Clock                → RealClock
18	 *
19	 * Topology:
20	 *   - All orchestrator containers, executor containers, the broker container,
21	 *     and the Redis container share the `agents-net` bridge network.
22	 *   - Orchestrators have the Docker socket mounted so they can `docker run`
23	 *     executor containers attached to the same bridge.
24	 *   - Runners reach the broker at http://broker:7000/callback via service-name DNS.
25	 *   - Any orchestrator drains any completion (opportunistic dispatch).
26	 */
27	
28	import type { RuntimePorts } from "../runtime-ports.js";
29	import { DockerRunAdapter, type DockerRunAdapterOpts } from "../executor/docker-run.js";
30	import { HttpBrokerAdapter, type HttpBrokerAdapterOpts } from "../broker/http.js";
31	import { GitWorkflowStateAdapter } from "../infra/workflow-state/git.js";
32	import { EnvCredentialAdapter } from "../infra/credential/env.js";
33	import { GitClonePullAdapter } from "../infra/workspace-pull/git-clone-pull.js";
34	import { StdoutJsonEmitter } from "../infra/emitter/stdout-json.js";
35	import { SimpleSleepScheduler } from "../infra/scheduler/simple-sleep.js";
36	import { RealClock } from "../infra/clock/real.js";
37	
38	export interface LocalDockerProfileOpts {
39	  /** Options forwarded to DockerRunAdapter. */
40	  executor?: DockerRunAdapterOpts;
41	  /** Options forwarded to HttpBrokerAdapter. */
42	  broker?: HttpBrokerAdapterOpts;
43	  /** Base URL of the Go broker service. Defaults to http://broker:7000. */
44	  brokerUrl?: string;
45	  /** Git identity for WorkflowStatePort operations. */
46	  gitAuthorEmail: string;
47	  gitAuthorName?: string;
48	  sshKeyPath?: string;
49	}
50	
51	/** The broker is part of the profile bundle so callers can call getCallbackUrl(). */
52	export interface LocalDockerProfileBundle extends RuntimePorts {
53	  broker: HttpBrokerAdapter;
54	  executor: DockerRunAdapter;
55	}
56	
57	/**
58	 * Create a RuntimePorts bundle wired for the local-docker profile.
59	 *
60	 * The broker's getCallbackUrl() returns the Go broker service callback
61	 * URL (e.g. http://broker:7000/callback). Pass this to ExecutorPortInput
62	 * as callbackUrl when submitting tasks.
63	 *
64	 * Example:
65	 *   const bundle = createLocalDockerProfile({ gitAuthorEmail: '...', brokerUrl: 'http://broker:7000' });
66	 *   const callbackUrl = bundle.broker.getCallbackUrl();
67	 *   // pass bundle to orchestrator concerns...
68	 *   bundle.executor.stopOrphanSweep(); // on graceful shutdown
69	 */
70	export function createLocalDockerProfile(
71	  opts: LocalDockerProfileOpts,
72	): LocalDockerProfileBundle {
73	  const brokerUrl = opts.brokerUrl ?? opts.broker?.brokerUrl ?? "http://broker:7000";
74	  const broker = new HttpBrokerAdapter(
75	    opts.broker ?? { brokerUrl },
76	  );
77	  const executor = new DockerRunAdapter({ ...opts.executor, broker });
78	  return {
79	    executor,
80	    broker,
81	    workflowState: new GitWorkflowStateAdapter({
82	      gitAuthorEmail: opts.gitAuthorEmail,
83	      gitAuthorName: opts.gitAuthorName,
84	      sshKeyPath: opts.sshKeyPath,
85	    }),
86	    credential: new EnvCredentialAdapter(),
87	    workspacePull: new GitClonePullAdapter(),
88	    emitter: new StdoutJsonEmitter(),
89	    scheduler: new SimpleSleepScheduler(),
90	    clock: new RealClock(),
91	  };
92	}
 1	/**
 2	 * local-subprocess profile factory.
 3	 *
 4	 * Bundles the Wave-3 adapter set into a RuntimePorts instance for the
 5	 * single-container, single-process topology: orchestrator and executor
 6	 * run as child processes inside the same image.
 7	 *
 8	 * Adapter set:
 9	 *   ExecutorPort         → SubProcessAdapter     (blocks in Wave 2; async in Wave 3/T5)
10	 *   CompletionBrokerPort → InMemoryBrokerAdapter   (Wave 3 / T3 — embedded HTTP receiver)
11	 *   WorkflowState        → GitWorkflowStateAdapter
12	 *   Credential           → EnvCredentialAdapter
13	 *   WorkspacePull        → GitClonePullAdapter
14	 *   EventEmitter         → StdoutJsonEmitter
15	 *   Scheduler            → SimpleSleepScheduler
16	 *   Clock                → RealClock
17	 */
18	
19	import type { RuntimePorts } from "../runtime-ports.js";
20	import { SubProcessAdapter, type SubProcessAdapterOpts } from "../executor/subprocess.js";
21	import { InMemoryBrokerAdapter, type InMemoryBrokerAdapterOpts } from "../broker/in-memory.js";
22	import { GitWorkflowStateAdapter } from "../infra/workflow-state/git.js";
23	import { EnvCredentialAdapter } from "../infra/credential/env.js";
24	import { GitClonePullAdapter } from "../infra/workspace-pull/git-clone-pull.js";
25	import { StdoutJsonEmitter } from "../infra/emitter/stdout-json.js";
26	import { SimpleSleepScheduler } from "../infra/scheduler/simple-sleep.js";
27	import { RealClock } from "../infra/clock/real.js";
28	
29	export interface LocalSubprocessProfileOpts {
30	  /** Options forwarded to SubProcessAdapter. */
31	  executor?: SubProcessAdapterOpts;
32	  /** Options forwarded to InMemoryBrokerAdapter. */
33	  broker?: InMemoryBrokerAdapterOpts;
34	  /** Git identity for WorkflowStatePort operations. */
35	  gitAuthorEmail: string;
36	  gitAuthorName?: string;
37	  sshKeyPath?: string;
38	}
39	
40	/** The broker is part of the profile bundle so callers can call start()/stop(). */
41	export interface LocalSubprocessProfileBundle extends RuntimePorts {
42	  broker: InMemoryBrokerAdapter;
43	}
44	
45	/**
46	 * Create a RuntimePorts bundle wired for the local-subprocess profile.
47	 *
48	 * Callers must call `bundle.broker.start()` after creation to bind the HTTP
49	 * receiver port, and `bundle.broker.stop()` on graceful shutdown.
50	 *
51	 * The broker is wired into the executor so that SubProcessAdapter.submit()
52	 * can call broker.register() before spawning the runner wrapper (T5 Wave-3).
53	 * The orchestrator then passes callbackUrl = broker.getCallbackUrl() in the
54	 * ExecutorPortInput when submitting tasks.
55	 *
56	 * Example:
57	 *   const bundle = createLocalSubprocessProfile({ gitAuthorEmail: '...' });
58	 *   const brokerPort = await bundle.broker.start();
59	 *   // pass bundle to orchestrator concerns...
60	 *   await bundle.broker.stop();
61	 */
62	export function createLocalSubprocessProfile(
63	  opts: LocalSubprocessProfileOpts,
64	): LocalSubprocessProfileBundle {
65	  const broker = new InMemoryBrokerAdapter(opts.broker);
66	  const executor = new SubProcessAdapter({ ...opts.executor, broker });
67	  return {
68	    executor,
69	    broker,
70	    workflowState: new GitWorkflowStateAdapter({
71	      gitAuthorEmail: opts.gitAuthorEmail,
72	      gitAuthorName: opts.gitAuthorName,
73	      sshKeyPath: opts.sshKeyPath,
74	    }),
75	    credential: new EnvCredentialAdapter(),
76	    workspacePull: new GitClonePullAdapter(),
77	    emitter: new StdoutJsonEmitter(),
78	    scheduler: new SimpleSleepScheduler(),
79	    clock: new RealClock(),
80	  };
81	}

