  1	/**
  2	 * T7/T2: Git-based claim protocol with task-branch creation and SHA contention detection.
  3	 *
  4	 * The orchestrator creates feature/<featureId>-<taskId> before committing the claim.
  5	 * The management repo is on the task branch from the moment the claim succeeds.
  6	 *
  7	 * Contention resolution is SHA-based, not identity-based:
  8	 *   - Competing agents create the task branch from the same main HEAD and race to push.
  9	 *   - First push wins (fast-forward). Loser gets a non-fast-forward rejection, fetches,
 10	 *     and compares SHA with origin/<taskBranch>.
 11	 *   - SHA match  → this agent's commit landed (rebase re-ordered the push) → won.
 12	 *   - SHA differ → another agent's commit is on remote HEAD → lost.
 13	 *
 14	 * Branch-already-exists handling (re-claim or blocked recovery):
 15	 *   - blocked_context null:  interrupted prior claim — checkout + reset to origin/<branch>.
 16	 *   - blocked_context non-null: blocked recovery path — return branch_blocked_recovery.
 17	 *
 18	 * Pre-commit jitter (50–500 ms, bounded by jitter_max_seconds) de-synchronises agents
 19	 * that pull from the same cron tick and reduces the collision rate.
 20	 */
 21	
 22	import { execSync, spawnSync } from "node:child_process";
 23	import { readFileSync, writeFileSync } from "node:fs";
 24	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
 25	import type { Task } from "./types.js";
 26	import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
 27	import { buildGitEnv } from "../git-env.js";
 28	import { normalizeTaskKeyOrder } from "../utils/task-yaml-io.js";
 29	
 30	// ── Public types ──────────────────────────────────────────────────────────────
 31	
 32	export interface ClaimTaskOptions {
 33	  /** Absolute path to the management (workspace) repo root. */
 34	  workspaceRoot: string;
 35	  /** Task ID to claim (e.g. "T7"). */
 36	  taskId: string;
 37	  /** Feature directory ID (e.g. "task-branch-lifecycle"). */
 38	  featureId: string;
 39	  /**
 40	   * GIT_AUTHOR_EMAIL for the claim commit.
 41	   * Sourced from the resolved environment by the caller — not read from process.env
 42	   * directly so the protocol is testable with arbitrary identities.
 43	   */
 44	  gitAuthorEmail: string;
 45	  /** GIT_AUTHOR_NAME for the claim commit. Defaults to gitAuthorEmail if omitted. */
 46	  gitAuthorName?: string;
 47	  /** SSH private key path for git push. Omit to rely on ambient SSH config. */
 48	  sshKeyPath?: string;
 49	  /**
 50	   * Upper bound on the random pre-commit jitter in seconds.
 51	   * Actual jitter is random(50ms, min(500ms, jitterMaxSeconds * 1000)).
 52	   * Default: 0.5.
 53	   */
 54	  jitterMaxSeconds?: number;
 55	  /**
 56	   * Base branch of the workspace repo (e.g. "main").
 57	   * The orchestrator is reset to this branch before claiming, and losers are
 58	   * reset back to it after a push rejection.
 59	   * Default: "main".
 60	   */
 61	  baseBranch?: string;
 62	  /** Skip the pre-commit jitter sleep. Intended for unit/integration tests. */
 63	  skipJitter?: boolean;
 64	  /**
 65	   * Skip all git operations (fetch / checkout / add / commit / push).
 66	   * The task YAML is still mutated on disk.
 67	   * Intended for unit tests that do not set up a real git repo.
 68	   */
 69	  skipGit?: boolean;
 70	}
 71	
 72	/**
 73	 * Result returned by claimTask.
 74	 *   won: true                     — this agent owns the task; proceed with implementation.
 75	 *   won: false, reason: ...       — claim failed or was lost.
 76	 */
 77	export type ClaimResult =
 78	  | { won: true }
 79	  | {
 80	      won: false;
 81	      reason:
 82	        | "task_not_ready"           // task.status !== "ready" when we read it
 83	        | "push_rejected"            // another agent's commit is on remote HEAD
 84	        | "post_claim_mismatch"      // won the push but YAML doesn't confirm our claim
 85	        | "branch_blocked_recovery"  // task branch exists + blocked_context non-null → S5
 86	        | "yaml_parse_error";        // task YAML is malformed — skip without claiming
 87	    };
 88	
 89	// ── Internal helpers ──────────────────────────────────────────────────────────
 90	
 91	function sleep(ms: number): Promise<void> {
 92	  return new Promise((resolve) => setTimeout(resolve, ms));
 93	}
 94	
 95	function readTask(
 96	  workspaceRoot: string,
 97	  featureId: string,
 98	  taskId: string,
 99	): Task | null {
100	  try {
101	    return normalizeTaskKeyOrder(
102	      parseYaml(
103	        readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
104	      ) as Record<string, unknown>,
105	    );
106	  } catch {
107	    return null;
108	  }
109	}
110	
111	function writeTask(workspaceRoot: string, featureId: string, task: Task): void {
112	  writeFileSync(
113	    taskYamlAbsPath(workspaceRoot, featureId, task.id),
114	    yamlStringify(task),
115	    "utf-8",
116	  );
117	}
118	
119	
120	/**
121	 * Check whether a branch exists on origin.
122	 * Uses `git ls-remote --exit-code`: exit 0 = found, exit 2 = not found.
123	 */
124	function remoteHasBranch(
125	  workspaceRoot: string,
126	  branch: string,
127	  env: NodeJS.ProcessEnv,
128	): boolean {
129	  const result = spawnSync(
130	    "git",
131	    ["-C", workspaceRoot, "ls-remote", "--exit-code", "origin", `refs/heads/${branch}`],
