139	/**
140	 * Attempt to atomically claim a `ready` task.
141	 *
142	 * On success the management repo's local HEAD is on the task branch
143	 * (feature/<featureId>-<taskId>) with the claim commit. The task YAML has
144	 * status: in_progress and task.branch set to the canonical task branch name.
145	 *
146	 * @returns `{ won: true }` if this agent successfully claimed the task.
147	 *          `{ won: false, reason }` if the claim failed or was lost.
148	 */
149	export async function claimTask(opts: ClaimTaskOptions): Promise<ClaimResult> {
150	  const {
151	    workspaceRoot,
152	    taskId,
153	    featureId,
154	    gitAuthorEmail,
155	    gitAuthorName = gitAuthorEmail,
156	    sshKeyPath,
157	    jitterMaxSeconds = 0.5,
158	    baseBranch = "main",
159	    skipJitter = false,
160	    skipGit = false,
161	  } = opts;
162	
163	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
164	
165	  // ── 1. Fetch + reset to clean base branch ─────────────────────────────────
166	  // Always start from a known-good state so the task YAML reflects the latest
167	  // remote state, not a stale local copy.
168	  if (!skipGit) {
169	    try {
170	      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
171	      // Checkout baseBranch first so reset --hard targets the right branch.
172	      // Without this, reset --hard moves whatever branch is currently checked
173	      // out (e.g. a task branch left behind by dispatchReviewer) to main's tip,
174	      // causing duplicate-commit injection on the next rebase.
175	      execSync(`git -C "${workspaceRoot}" checkout "${baseBranch}"`, { env, stdio: "pipe" });
176	      execSync(
177	        `git -C "${workspaceRoot}" reset --hard "origin/${baseBranch}"`,
178	        { env, stdio: "pipe" },
179	      );
180	    } catch {
181	      return { won: false, reason: "push_rejected" };
182	    }
183	  }
184	
185	  // ── 2. Read task from disk; verify it is still ready ─────────────────────
186	  // `let` so we can rebind after inheriting an existing task branch (case b).
187	  let task = readTask(workspaceRoot, featureId, taskId);
188	  if (task === null) {
189	    return { won: false, reason: "yaml_parse_error" };
190	  }
191	  if (task.status !== "ready") {
192	    return { won: false, reason: "task_not_ready" };
193	  }
194	
195	  // ── 3. Determine task branch; handle branch-exists cases ─────────────────
196	  const branch = taskBranchName(featureId, taskId);
197	
198	  if (!skipGit) {
199	    const branchExists = remoteHasBranch(workspaceRoot, branch, env);
200	
201	    if (!branchExists) {
202	      // Case a: first claim — create the task branch from current HEAD (clean main).
203	      try {
204	        execSync(
205	          `git -C "${workspaceRoot}" checkout -b "${branch}"`,
206	          { env, stdio: "pipe" },
207	        );
208	      } catch {
209	        tryResetToRemote(workspaceRoot, baseBranch, env);
210	        return { won: false, reason: "push_rejected" };
211	      }
212	    } else if (!task.blocked_context) {
213	      // Case b: branch exists + no blocked_context — interrupted prior claim.
214	      // Checkout the existing branch and reset to origin state.
215	      try {
216	        execSync(
217	          `git -C "${workspaceRoot}" checkout "${branch}"`,
218	          { env, stdio: "pipe" },
219	        );
220	        execSync(
221	          `git -C "${workspaceRoot}" reset --hard "origin/${branch}"`,
222	          { env, stdio: "pipe" },
223	        );
224	      } catch {
225	        tryResetToRemote(workspaceRoot, baseBranch, env);
226	        return { won: false, reason: "push_rejected" };
227	      }
228	      // Re-read YAML from the branch state — another agent may have already
229	      // committed a claim here while we were checking. If the task is no longer
230	      // "ready" on this branch we lost the race.
231	      const branchTask = readTask(workspaceRoot, featureId, taskId);
232	      if (branchTask === null) {
233	        // Malformed YAML on the task branch. Use the already-parsed main copy
234	        // to write a blocked state and push it, so the task is no longer seen
235	        // as eligible on subsequent cycles.
236	        task.status = "blocked";
237	        task.blocked_reason = "yaml_parse_error";
238	        task.blocked_suggestion =
239	          "Task YAML was malformed on the task branch. Fix the YAML on the branch and reset status to ready.";
240	        writeTask(workspaceRoot, featureId, task);
241	        try {
242	          const repairRelPath = taskYamlRelPath(featureId, taskId);
243	          execSync(`git -C "${workspaceRoot}" add "${repairRelPath}"`, { env, stdio: "pipe" });
244	          execSync(
245	            `git -C "${workspaceRoot}" commit -m "chore(${taskId}): block — malformed YAML on task branch"`,
246	            { env, stdio: "pipe" },
247	          );
248	          spawnSync("git", ["-C", workspaceRoot, "push", "origin", branch], { env, encoding: "utf-8" });
249	        } catch { /* best effort — blocked state written locally even if push fails */ }
250	        tryResetToRemote(workspaceRoot, baseBranch, env);
251	        // Delete the stale local branch so a future claim (after the YAML is fixed)
252	        // can use `git checkout -b` cleanly. Without this, a rejected repair push
253	        // leaves a diverged local branch that blocks case-(a) fresh claims forever.
254	        try {
255	          execSync(`git -C "${workspaceRoot}" branch -D "${branch}"`, { env, stdio: "pipe" });
