257	        return { won: false, reason: "yaml_parse_error" };
258	      }
259	      task = branchTask;
260	      if (task.status !== "ready") {
261	        tryResetToRemote(workspaceRoot, baseBranch, env);
262	        return { won: false, reason: "push_rejected" };
263	      }
264	    } else {
265	      // Case c: branch exists + blocked_context non-null — blocked recovery (S5).
266	      // Do not attempt a new claim; the caller handles the recovery flow.
267	      return { won: false, reason: "branch_blocked_recovery" };
268	    }
269	  }
270	
271	  // ── 4. Pre-commit jitter ──────────────────────────────────────────────────
272	  if (!skipJitter) {
273	    const maxMs = Math.min(jitterMaxSeconds * 1000, 500);
274	    const minMs = 50;
275	    const jitterMs = minMs + Math.random() * Math.max(0, maxMs - minMs);
276	    await sleep(jitterMs);
277	  }
278	
279	  // ── 5. Mutate task YAML ───────────────────────────────────────────────────
280	  const now = new Date().toISOString();
281	  task.status = "in_progress";
282	  task.branch = branch;
283	  // Clear blocked_context on every fresh claim. If the task was previously
284	  // blocked and then unblocked back to `ready`, the prior blocked_context
285	  // is stale once we're claiming a new run — keeping it would re-route
286	  // future re-claims down the blocked-recovery path on case (c) below.
287	  task.blocked_context = null;
288	  task.execution.last_updated_by = gitAuthorEmail;
289	  task.execution.last_updated_at = now;
290	  task.log.push({
291	    action: "claimed",
292	    by: gitAuthorEmail,
293	    at: now,
294	    note: "Claimed via git-based claim protocol.",
295	  });
296	  writeTask(workspaceRoot, featureId, task);
297	
298	  if (skipGit) {
299	    return { won: true };
300	  }
301	
302	  // ── 6. git add + commit ───────────────────────────────────────────────────
303	  const relPath = taskYamlRelPath(featureId, taskId);
304	
305	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
306	    env,
307	    stdio: "pipe",
308	  });
309	  execSync(
310	    `git -C "${workspaceRoot}" commit -m "chore(${taskId}): claim — status in_progress"`,
311	    { env, stdio: "pipe" },
312	  );
313	
314	  // Record the commit SHA — this is the arbitration token.
315	  const ourSha = execSync(
316	    `git -C "${workspaceRoot}" rev-parse HEAD`,
317	    { env, stdio: "pipe", encoding: "utf-8" },
318	  ).trim();
319	
320	  // ── 7. git push to task branch ────────────────────────────────────────────
321	  const pushResult = spawnSync(
322	    "git",
323	    ["-C", workspaceRoot, "push", "origin", branch],
324	    { env, encoding: "utf-8" },
325	  );
326	
327	  if (pushResult.status !== 0) {
328	    // Push rejected — fetch and compare SHA against origin/<branch>.
329	    try {
330	      execSync(
331	        `git -C "${workspaceRoot}" fetch origin "${branch}"`,
332	        { env, stdio: "pipe" },
333	      );
334	    } catch {
335	      tryResetToRemote(workspaceRoot, baseBranch, env);
336	      return { won: false, reason: "push_rejected" };
337	    }
338	
339	    const remoteHeadSha = execSync(
340	      `git -C "${workspaceRoot}" rev-parse "origin/${branch}"`,
341	      { env, stdio: "pipe", encoding: "utf-8" },
342	    ).trim();
343	
344	    if (remoteHeadSha !== ourSha) {
345	      // Another agent's commit is on the remote — we lost.
346	      tryResetToRemote(workspaceRoot, baseBranch, env);
347	      return { won: false, reason: "push_rejected" };
348	    }
349	
350	    // remoteHeadSha === ourSha: our commit landed despite the rejection. We won.
351	  }
352	
353	  // ── 8. Post-claim verification ────────────────────────────────────────────
354	  const confirmed = readTask(workspaceRoot, featureId, taskId);
355	  if (
356	    confirmed === null ||
357	    confirmed.status !== "in_progress" ||
358	    confirmed.execution.last_updated_by !== gitAuthorEmail
359	  ) {
360	    return { won: false, reason: "post_claim_mismatch" };
361	  }
362	
363	  return { won: true };
364	}
365	
366	// ── Utilities ─────────────────────────────────────────────────────────────────
367	
368	/**
369	 * Best-effort reset of the local repo to origin/<baseBranch>.
370	 * Used after losing a push race so the next activation starts from a clean state.
371	 */
372	function tryResetToRemote(
373	  workspaceRoot: string,
374	  baseBranch: string,
375	  env: NodeJS.ProcessEnv,
376	): void {
377	  try {
378	    execSync(
379	      `git -C "${workspaceRoot}" checkout "${baseBranch}"`,
380	      { env, stdio: "pipe" },
381	    );
382	    execSync(
383	      `git -C "${workspaceRoot}" reset --hard "origin/${baseBranch}"`,
384	      { env, stdio: "pipe" },
385	    );
386	  } catch {
387	    // Intentionally ignored — best-effort cleanup.
388	  }
389	}

