/**
 * ClaudeDockerRunAdapter — DockerRunAdapter specialised for the Claude executor.
 *
 * Owns the Claude executor's env contract: reads Claude-specific runtime
 * requirements directly from process.env and merges them into extraEnv before
 * delegating to the generic DockerRunAdapter. The base class has no knowledge
 * of which executor it is running.
 */

import { DockerRunAdapter, type DockerRunAdapterOpts } from "./docker-run.js";

const CLAUDE_EXECUTOR_PASSTHROUGH = [
  "ANTHROPIC_API_KEY",
  "GIT_AUTHOR_NAME",
  "GIT_AUTHOR_EMAIL",
  "WORKFLOW_LOCAL_PATH",
  "MCP_RAG_URL",
  "GITNEXUS_MCP_URL",
  "FIGMA_PERSONAL_ACCESS_TOKEN",
  // MAX_TURNS is set on the orchestrator service in docker-compose
  // (see runtime/orchestrator/docs/OPERATOR-GUIDE.md). The DockerRunAdapter
  // does not generally forward process.env, so MAX_TURNS must be explicitly
  // listed here for the Claude executor container to inherit it.
  "MAX_TURNS",
] as const;

export class ClaudeDockerRunAdapter extends DockerRunAdapter {
  constructor(opts: DockerRunAdapterOpts = {}) {
    const claudeEnv: Record<string, string> = {};
    for (const key of CLAUDE_EXECUTOR_PASSTHROUGH) {
      const val = process.env[key];
      if (val !== undefined) claudeEnv[key] = val;
    }
    super({
      ...opts,
      extraEnv: { ...claudeEnv, ...(opts.extraEnv ?? {}) },
    });
  }
}
/**
 * RuntimePorts — the full set of port interfaces the orchestrator core depends on.
 *
 * A profile factory creates one RuntimePorts bundle at startup; the bundle is
 * then injected into the orchestrator concerns. The core never touches concrete
 * adapter classes — only this interface bundle.
 */

import type {
  ExecutorPort,
  CompletionBrokerPort,
  WorkflowStatePort,
  CredentialPort,
  WorkspacePullPort,
  EventEmitterPort,
  SchedulerPort,
  ClockPort,
} from "@workflow/runtime-abi";

export interface RuntimePorts {
  /** Spawn an executor; return a handle immediately (async in Wave 3+). */
  executor: ExecutorPort;

  /** Completion queue — in-flight registry + peek-and-lock drain. */
  broker: CompletionBrokerPort;

  /** Read/write workflow state (task YAMLs, logs). */
  workflowState: WorkflowStatePort;

  /** Provide credentials (GitHub token, SSH key path) to executors. */
  credential: CredentialPort;

  /** Materialize workspace repos (clone + pull). */
  workspacePull: WorkspacePullPort;

  /** Emit structured events / metrics. */
  emitter: EventEmitterPort;

  /** Control cycle cadence (sleep between cycles). */
  scheduler: SchedulerPort;

  /** Wall-clock time and sleep (mockable in tests). */
  clock: ClockPort;
}

