// ─── toSafeIso ───────────────────────────────────────────────────────────────

describe("toSafeIso", () => {
  it("replaces all colons with dashes", () => {
    expect(toSafeIso("2026-04-14T12:00:00.000Z")).toBe(
      "2026-04-14T12-00-00.000Z",
    );
  });

  it("leaves timestamps without colons unchanged", () => {
    expect(toSafeIso("2026-04-14")).toBe("2026-04-14");
  });
});

