/**
 * Dispatch reconciler (T5 — standalone-executor-hardening).
 *
 * A backstop for the one case the dispatch stream can't self-heal: *no
 * dispatcher alive at all* so the job sits unclaimed and `XAUTOCLAIM` never
 * fires.
 *
 * Algorithm:
 *   For each `in_progress` task with a persisted `execution_handle` whose
 *   `execution.last_updated_at` is older than EXECUTION_DEADLINE:
 *
 *     1. Count `reconciler_reenqueued` log entries. If count >= MAX_RETRIES,
 *        transition to `blocked` (reason: dispatch_reconciler_max_retries).
 *     2. Otherwise, generate a fresh nonce, re-register handle+nonce with the
 *        broker (overwrites the stale nonce), re-enqueue the DispatchJob.
 *        T4's per-handle spawn lock prevents double-spawn when a dispatcher
 *        IS alive but slow.
 *     3. Append a `reconciler_reenqueued` log entry and push the YAML.
 *
 * Only runs on the `local-docker` profile — on `local-subprocess` completions
 * are drained inline and there is no external dispatcher to fail.
 *
 * Environment:
 *   EXECUTION_DEADLINE_MS  — milliseconds after last_updated_at before a
 *                            job is considered stuck. Default: 7 200 000 (2h).
 *   DISPATCH_RECONCILE_MAX_RETRIES — max re-enqueues before blocking.
 *                            Default: 3.
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { CompletionBrokerPort, ExecutorPort } from "@workflow/runtime-abi";
import { DISPATCH_STREAM_KEY, type DispatchJob } from "@workflow/runtime-abi";
import {
  resolveRepoGitUrl,
  resolveRepoBaseBranch,
  parseManagementRepoCoords,
  loadWorkspaceModelPolicy,
} from "../config/workspace-config.js";
import { resolveModel } from "../config/resolve-model-policy.js";
import { taskYamlAbsPath, featureBranchName } from "../paths.js";
import { mutateTaskYamlDirect } from "../task/mutate-yaml-direct.js";
import { appendLogEntry } from "../task/append-log.js";
import { normalizeTaskKeyOrder } from "../utils/task-yaml-io.js";
import type { Task } from "../task/types.js";

// ── Constants ─────────────────────────────────────────────────────────────────

const EXECUTION_DEADLINE_MS = parseInt(
  process.env.EXECUTION_DEADLINE_MS ?? String(7_200_000),
  10,
);

const DISPATCH_RECONCILE_MAX_RETRIES = parseInt(
  process.env.DISPATCH_RECONCILE_MAX_RETRIES ?? "3",
  10,
);

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DispatchReconcilerOpts {
  workspaceRoots: string[];
  /** Must be a QueueDispatchAdapter on local-docker. */
  executor: ExecutorPort;
  broker: CompletionBrokerPort;
  workspacesDir: string;
  callbackUrl: string;
  budgetTokens?: number;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface DispatchReconcilerResult {
  reEnqueued: number;
  blocked: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function readTaskSafe(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
): Task | null {
  try {
    const raw = parseYaml(
      readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
    ) as Record<string, unknown>;
    return normalizeTaskKeyOrder(raw);
  } catch {
    return null;
  }
}

function isStuck(lastUpdatedAt: string | null | undefined): boolean {
  if (!lastUpdatedAt) return false;
  const updated = new Date(lastUpdatedAt).getTime();
  if (Number.isNaN(updated)) return false;
  return Date.now() - updated > EXECUTION_DEADLINE_MS;
}

function countReEnqueuedEntries(task: Task): number {
  return (task.log ?? []).filter((e) => e.action === "reconciler_reenqueued").length;
}

/**
 * Discover all in_progress tasks with a persisted execution_handle across
 * the given workspace roots.
 */
function findStuckInProgressTasks(workspaceRoots: string[]): Array<{
  workspaceRoot: string;
  featureId: string;
  task: Task;
}> {
  const results: Array<{ workspaceRoot: string; featureId: string; task: Task }> = [];

  for (const wsRoot of workspaceRoots) {
    const featuresDir = join(wsRoot, "docs", "features");
    if (!existsSync(featuresDir)) continue;

    let featureDirs: string[];
    try {
      const { readdirSync } = await_import_readdirSync();
      featureDirs = readdirSync(featuresDir);
    } catch {
      continue;
    }

    for (const featureId of featureDirs) {
      const tasksDir = join(featuresDir, featureId, "tasks");
      if (!existsSync(tasksDir)) continue;

      let taskFiles: string[];
      try {
        const { readdirSync } = await_import_readdirSync();
        taskFiles = readdirSync(tasksDir).filter((f) => f.endsWith(".yaml"));
      } catch {
        continue;
      }

      for (const taskFile of taskFiles) {
        const taskId = taskFile.replace(/\.yaml$/, "");
        const task = readTaskSafe(wsRoot, featureId, taskId);
        if (!task) continue;
        if (task.status !== "in_progress") continue;
        if (!task.execution_handle) continue;
        if (!isStuck(task.execution?.last_updated_at)) continue;

        results.push({ workspaceRoot: wsRoot, featureId, task });
      }
    }
  }

  return results;
}

// We need a sync readdirSync — use Node's built-in.
function await_import_readdirSync(): { readdirSync: (path: string) => string[] } {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { readdirSync } = require("node:fs") as typeof import("node:fs");
  return { readdirSync };
}

// ── Main export ───────────────────────────────────────────────────────────────

/**
 * Run one reconciler sweep across all workspace roots.
 *
 * For each stuck in_progress task:
 *   - If retries exhausted → set blocked.
 *   - Otherwise → re-enqueue via executor.submit() with a fresh nonce.
 */
export async function runDispatchReconciler(
  opts: DispatchReconcilerOpts,
): Promise<DispatchReconcilerResult> {
  const {
    workspaceRoots,
    executor,
    broker,
    workspacesDir,
    callbackUrl,
    budgetTokens,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    emit,
  } = opts;

  let reEnqueued = 0;
  let blocked = 0;

  const stuckTasks = findStuckInProgressTasks(workspaceRoots);

  for (const { workspaceRoot, featureId, task } of stuckTasks) {
    const taskId = task.id;
    const handle = task.execution_handle as string;
    const taskBranch = task.branch;

    emit({
      type: "reconciler_stuck_task",
      task_id: taskId,
      feature_id: featureId,
      handle,
      last_updated_at: task.execution?.last_updated_at,
    });

    const retryCount = countReEnqueuedEntries(task);

    if (retryCount >= DISPATCH_RECONCILE_MAX_RETRIES) {
      // Exhausted retries → block the task.
      const mutateErr = mutateTaskYamlDirect({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        status: "blocked",
        logEntry: {
          action: "blocked",
          by: gitAuthorEmail,
          note: `Dispatch reconciler: no completion after ${DISPATCH_RECONCILE_MAX_RETRIES} re-enqueues.`,
        },
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        commitMessage: `chore(${taskId}): reconciler — blocked after max re-enqueues`,
      });
      if (mutateErr) {
        emit({
          type: "reconciler_block_failed",
          task_id: taskId,
          feature_id: featureId,
          details: mutateErr,
        });
      } else {
        emit({
          type: "reconciler_task_blocked",
          task_id: taskId,
          feature_id: featureId,
          retries: retryCount,
        });
        blocked++;
      }
      continue;
    }

    // Re-enqueue with a fresh nonce.
    const nonce = randomUUID();
    const startedAt = new Date().toISOString();

    // Re-register the handle with the broker (overwrites stale nonce).
    try {
      await broker.register(handle, nonce, {
        kind: "impl",
        task_id: taskId,
        feature_id: featureId,
        started_at: startedAt,
      });
    } catch (e) {
      emit({
        type: "reconciler_register_failed",
        task_id: taskId,
        feature_id: featureId,
        details: String(e),
      });
      continue;
    }

    // Resolve task-repo context from workspace config.
    let taskRepoUrl: string;
    let taskRepoBaseBranch: string;
    let implModel: string;
    let mgmtRepoUrl: string;
    let workspaceId: string;

    try {
      taskRepoUrl = resolveRepoGitUrl(workspaceRoot, task.repo);
      taskRepoBaseBranch = resolveRepoBaseBranch(workspaceRoot, task.repo);
      const modelPolicy = loadWorkspaceModelPolicy(workspaceRoot);
      implModel = resolveModel(modelPolicy, {}, "implementation", taskId);
      const mgmtCoords = parseManagementRepoCoords(workspaceRoot);
      mgmtRepoUrl = mgmtCoords.repoUrl;

      const { parse: yaml } = await import("yaml");
      const { readFileSync: rfs } = await import("node:fs");
      const { join: pathJoin } = await import("node:path");
      const { workspaceYamlPath } = await import("../paths.js");
      const wsYaml = yaml(rfs(workspaceYamlPath(workspaceRoot), "utf-8")) as {
        workspace_id: string;
      };
      workspaceId = wsYaml.workspace_id;
    } catch (e) {
      emit({
        type: "reconciler_context_error",
        task_id: taskId,
        feature_id: featureId,
        details: String(e),
      });
      continue;
    }

    // Build the DispatchJob (same structure as QueueDispatchAdapter.submit).
    const job: DispatchJob = {
      handle,
      nonce,
      kind: "impl",
      task_id: taskId,
      feature_id: featureId,
      workspace_id: workspaceId,
      task_repo_url: taskRepoUrl,
      task_repo_branch: taskBranch,
      task_base_branch: featureBranchName(featureId),
      task_repo_base_branch: taskRepoBaseBranch,
      mgmt_repo_url: mgmtRepoUrl,
      executor_workdir: `${workspacesDir}/exec-${handle}`,
      callback_url: callbackUrl,
      enqueued_at: startedAt,
      ...(budgetTokens !== undefined ? { budget_tokens: budgetTokens } : {}),
      ...(implModel ? { implementation_model: implModel } : {}),
    };

    // XADD to the dispatch stream via the executor adapter.
    // We call submit() on the QueueDispatchAdapter — it will re-register the
    // handle (idempotent) and XADD the job.  We skip broker.register here since
    // we already called it above.
    try {
      // Direct XADD — bypass submit()'s broker.register call by calling the
      // underlying Redis XADD manually. We already re-registered above.
      // Use executor's submit with a minimal ExecutorPortInput so we don't
      // double-register; the QueueDispatchAdapter.submit() calls register
      // again which is fine (broker idempotent).
      await executor.submit({
        taskId,
        featureId,
        workspaceId,
        handle,
        taskRepoUrl,
        taskRepoBranch: taskBranch,
        taskBaseBranch: featureBranchName(featureId),
        taskRepoBaseBranch,
        executorWorkdir: job.executor_workdir,
        mgmtRepoUrl,
        resultPath: `/tmp/executor-result-${taskId}.json`,
        callbackUrl,
        nonce,
        budgetTokens,
        implementationModel: implModel,
        sshPrivateKey: "",
        githubToken: "",
      });
    } catch (e) {
      emit({
        type: "reconciler_reenqueue_failed",
        task_id: taskId,
        feature_id: featureId,
        handle,
        details: String(e),
      });
      continue;
    }

    // Append log entry to the task YAML.
    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: {
        action: "reconciler_reenqueued",
        by: gitAuthorEmail,
        note: `Dispatch reconciler: re-enqueued (attempt ${retryCount + 1} of ${DISPATCH_RECONCILE_MAX_RETRIES}).`,
        handle,
        stream: DISPATCH_STREAM_KEY,
      },
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });

    if (logErr) {
      emit({
        type: "reconciler_log_failed",
        task_id: taskId,
        feature_id: featureId,
        details: logErr,
      });
    } else {
      emit({
        type: "reconciler_reenqueued",
        task_id: taskId,
        feature_id: featureId,
        handle,
        attempt: retryCount + 1,
        max: DISPATCH_RECONCILE_MAX_RETRIES,
      });
      reEnqueued++;
    }
  }

  return { reEnqueued, blocked };
}

