import { describe, it, expect, vi } from "vitest";

import { StdoutJsonEmitter } from "../src/infra/emitter/stdout-json.js";
import { SimpleSleepScheduler } from "../src/infra/scheduler/simple-sleep.js";
import { RealClock } from "../src/infra/clock/real.js";
import { EnvCredentialAdapter } from "../src/infra/credential/env.js";
import { NullBrokerAdapter } from "../src/broker/null.js";
import { SubProcessAdapter } from "../src/executor/subprocess.js";
import { createLocalSubprocessProfile } from "../src/profiles/local-subprocess.js";

// ── 1. StdoutJsonEmitter ──────────────────────────────────────────────────────

describe("StdoutJsonEmitter", () => {
  it("emits a JSON line with type and at fields", () => {
    const lines: string[] = [];
    vi.spyOn(console, "log").mockImplementation((msg: string) => lines.push(msg));

