    broker: broker as never,
    redisClient: redisClient as never,
    workspacesDir: "/workspaces",
  });
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("QueueDispatchAdapter", () => {
  let broker: FakeBroker;
  let redis: FakeRedisClient;
  let adapter: QueueDispatchAdapter;

  beforeEach(() => {
    broker = new FakeBroker();
    redis = new FakeRedisClient();
    redis.connected = true; // simulate pre-connected client
    adapter = makeAdapter(broker, redis);
  });

  // ── 1. Broker registration before XADD ───────────────────────────────────

  it("registers handle+nonce with the broker before enqueuing", async () => {
    const input = makeInput();
    await adapter.submit(input);

    expect(broker.registrations).toHaveLength(1);
    expect(broker.registrations[0]!.handle).toBe(input.handle);
    expect(broker.registrations[0]!.nonce).toBe(input.nonce);
    expect(broker.registrations[0]!.metadata.task_id).toBe(input.taskId);
    expect(broker.registrations[0]!.metadata.feature_id).toBe(input.featureId);
  });

  it("registers broker before the stream XADD (ordering via call sequence)", async () => {
    const callOrder: string[] = [];
    const origRegister = broker.register.bind(broker);
    const origXAdd = redis.xAdd.bind(redis);
    broker.register = async (...args) => { callOrder.push("register"); return origRegister(...args); };
    redis.xAdd = async (...args) => { callOrder.push("xAdd"); return origXAdd(...args); };

    await adapter.submit(makeInput());

    expect(callOrder).toEqual(["register", "xAdd"]);
  });

  // ── 2. Dispatch stream XADD ──────────────────────────────────────────────

  it("XADDs exactly one entry to the dispatch stream", async () => {
    await adapter.submit(makeInput());

    const entries = redis.streams.get(DISPATCH_STREAM_KEY);
    expect(entries).toHaveLength(1);
  });

  it("uses the correct dispatch stream key", async () => {
    await adapter.submit(makeInput());

    expect(redis.streams.has(DISPATCH_STREAM_KEY)).toBe(true);
    expect(DISPATCH_STREAM_KEY).toBe("platform:dispatch");
  });

  // ── 3. DispatchJob field mapping ─────────────────────────────────────────

  it("maps handle, nonce, and kind correctly", async () => {
    const input = makeInput();
    await adapter.submit(input);

    const entry = redis.lastEntry(DISPATCH_STREAM_KEY)!;
    expect(entry.fields.handle).toBe(input.handle);
    expect(entry.fields.nonce).toBe(input.nonce);
    expect(entry.fields.kind).toBe("impl");
  });

  it("maps task identity fields correctly", async () => {
    const input = makeInput();
    await adapter.submit(input);

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    expect(f.task_id).toBe(input.taskId);
    expect(f.feature_id).toBe(input.featureId);
    expect(f.workspace_id).toBe(input.workspaceId);
  });

  it("maps repo/branch fields correctly", async () => {
    const input = makeInput();
    await adapter.submit(input);

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    expect(f.task_repo_url).toBe(input.taskRepoUrl);
    expect(f.task_repo_branch).toBe(input.taskRepoBranch);
    expect(f.task_base_branch).toBe(input.taskBaseBranch);
    expect(f.task_repo_base_branch).toBe(input.taskRepoBaseBranch);
    expect(f.mgmt_repo_url).toBe(input.mgmtRepoUrl);
    expect(f.executor_workdir).toBe(input.executorWorkdir);
    expect(f.callback_url).toBe(input.callbackUrl);
  });

  it("includes budget_tokens and implementation_model when provided", async () => {
    const input = makeInput({ budgetTokens: 300_000, implementationModel: "claude-opus-4-8" });
    await adapter.submit(input);

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    expect(f.budget_tokens).toBe("300000");
    expect(f.implementation_model).toBe("claude-opus-4-8");
  });

  it("omits budget_tokens when not provided", async () => {
    const input = makeInput({ budgetTokens: undefined });
    await adapter.submit(input);

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    expect(f.budget_tokens).toBeUndefined();
  });

  it("includes enqueued_at as an ISO 8601 string", async () => {
    await adapter.submit(makeInput());

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    expect(f.enqueued_at).toBeDefined();
    expect(() => new Date(f.enqueued_at!)).not.toThrow();
    expect(new Date(f.enqueued_at!).toISOString()).toBe(f.enqueued_at);
  });

  // ── 4. No secrets in the stream entry ───────────────────────────────────

  it("does NOT include sshPrivateKey in the dispatch job", async () => {
    const input = makeInput({ sshPrivateKey: "super-secret-key" });
    await adapter.submit(input);

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    const allValues = Object.values(f).join(" ");
    expect(allValues).not.toContain("super-secret-key");
    expect(f).not.toHaveProperty("sshPrivateKey");
    expect(f).not.toHaveProperty("ssh_private_key");
    expect(f).not.toHaveProperty("SSH_PRIVATE_KEY");
  });

  it("does NOT include githubToken in the dispatch job", async () => {
    const input = makeInput({ githubToken: "ghp_secret_token" });
    await adapter.submit(input);

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    const allValues = Object.values(f).join(" ");
    expect(allValues).not.toContain("ghp_secret_token");
    expect(f).not.toHaveProperty("githubToken");
    expect(f).not.toHaveProperty("github_token");
    expect(f).not.toHaveProperty("GITHUB_TOKEN");
  });

  // ── 5. ack() delegates to broker ────────────────────────────────────────

  it("ack() calls broker.ack() with the handle", async () => {
    await adapter.ack("my-handle");

    expect(broker.ackedHandles).toContain("my-handle");
  });

  // ── 6. readResult() returns tombstone ───────────────────────────────────

  it("readResult() returns a failed tombstone (results arrive via broker)", async () => {
    const result = await adapter.readResult("any-handle");

    expect(result.terminal_status).toBe("failed");
    expect(result.blocked_reason).toBe("handle_not_found");
  });

  // ── 7. submit() returns handle immediately ───────────────────────────────

  it("submit() resolves to the exact handle from input", async () => {
    const input = makeInput({ handle: "my-specific-handle" });
    const returned = await adapter.submit(input);

    expect(returned).toBe("my-specific-handle");
  });

  // ── 8. kind=rebase mapping ───────────────────────────────────────────────

  it("maps kind=rebase correctly to the stream entry", async () => {
    const input = makeInput({ kind: "rebase" as const });
    await adapter.submit(input);

    const f = redis.lastEntry(DISPATCH_STREAM_KEY)!.fields;
    expect(f.kind).toBe("rebase");
  });
});

